  for(var g=1;g<=gen;g++){
    var prevPositions=positions.slice();
    positions=[];
    var count=Math.pow(3,g);
    var spacing=Math.min(60,800/(count+1));
    var startX=550-(count-1)*spacing/2;
    for(var i=0;i<count;i++){
      var x=startX+i*spacing;
      var y=startY+g*levelH;
      positions.push([x,y]);
