var gNeutron=defs.gradient('radial',function(add){
  add.stop(0,'#f0f0ea');add.stop(0.5,'#d0d0c8');add.stop(1,'#909088');
});
gNeutron.attr({cx:'35%',cy:'35%',r:'65%'});

// Seeded random
function seededRand(seed){var s=seed;return function(){s=(s*16807)%2147483647;return(s-1)/2147483646;};}

// Draw a nucleon cluster
function drawCluster(group,cx,cy,rx,ry,count,seed,pinch){
  var rng=seededRand(seed);
  var nucleons=[];
  var attempts=0;
  while(nucleons.length<count&&attempts<count*20){
    attempts++;
    var angle=rng()*Math.PI*2;
    var r=Math.sqrt(rng());
    var x=cx+Math.cos(angle)*r*rx;
    var y=cy+Math.sin(angle)*r*ry;
    // Apply pinch for dumbbell shape
    if(pinch){
      var normY=(y-cy)/ry;
      var pinchFactor=1-0.35*Math.exp(-normY*normY*8);
      x=cx+(x-cx)*pinchFactor;
    }
    var tooClose=false;
    for(var i=0;i<nucleons.length;i++){
      var dx=x-nucleons[i][0],dy=y-nucleons[i][1];
      if(dx*dx+dy*dy<100){tooClose=true;break;}
    }
    if(!tooClose)nucleons.push([x,y]);
  }
  // Sort by y for painter's algorithm
  nucleons.sort(function(a,b){return a[1]-b[1];});
  var rad=Math.min(rx,ry)/Math.sqrt(count)*1.8;
  for(var i=0;i<nucleons.length;i++){
    var col=(i%2===0)?gGreen:gWhite;
    group.circle(rad*2).center(nucleons[i][0],nucleons[i][1]).fill(col).stroke({color:'#555',width:0.3});
  }
}

