var draw=SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0,0,W,H);

// Gradients
var defs=draw.defs();
var gGreen=defs.gradient('radial',function(add){
  add.stop(0,'#d4edaa');add.stop(0.35,'#8bc34a');add.stop(0.7,'#5a9e2f');add.stop(1,'#3d7a1a');
});
