(function(){
var W=1200,H=850;
var draw=SVG().addTo(document.getElementById('container')).size('100%','100%');
draw.viewbox(0,0,W,H);

// Gradients
var defs=draw.defs();
var gGreen=defs.gradient('radial',function(add){
  add.stop(0,'#d4edaa');add.stop(0.35,'#8bc34a');add.stop(0.7,'#5a9e2f');add.stop(1,'#3d7a1a');
});
gGreen.attr({cx:'35%',cy:'35%',r:'65%'});
var gWhite=defs.gradient('radial',function(add){
  add.stop(0,'#ffffff');add.stop(0.35,'#f0f0e8');add.stop(0.7,'#d8d8cc');add.stop(1,'#a8a898');
});
gWhite.attr({cx:'35%',cy:'35%',r:'65%'});
var gNeutron=defs.gradient('radial',function(add){
  add.stop(0,'#f8f8f2');add.stop(0.4,'#e0e0d8');add.stop(0.8,'#b8b8ac');add.stop(1,'#909088');
});
gNeutron.attr({cx:'35%',cy:'35%',r:'65%'});

function seededRand(seed){var s=seed;return function(){s=(s*16807)%2147483647;return(s-1)/2147483646;};}

function drawCluster(group,cx,cy,rx,ry,count,seed,pinch){
  var rng=seededRand(seed);
  var nucleons=[];
  var attempts=0;
  while(nucleons.length<count&&attempts<count*30){
    attempts++;
    var angle=rng()*Math.PI*2;
    var r=Math.sqrt(rng());
    var x=cx+Math.cos(angle)*r*rx;
    var y=cy+Math.sin(angle)*r*ry;
    if(pinch){
      var normY=(y-cy)/ry;
      var pinchFactor=1-0.35*Math.exp(-normY*normY*8);
      x=cx+(x-cx)*pinchFactor;
    }
    var tooClose=false;
    var minDist=Math.min(rx,ry)*0.28;
    for(var i=0;i<nucleons.length;i++){
      var dx=x-nucleons[i][0],dy=y-nucleons[i][1];
      if(dx*dx+dy*dy<minDist*minDist){tooClose=true;break;}
    }
    if(!tooClose)nucleons.push([x,y]);
  }
  nucleons.sort(function(a,b){return a[1]-b[1];});
  var rad=Math.min(rx,ry)/Math.sqrt(count)*2.2;
  for(var i=0;i<nucleons.length;i++){
    var col=(i%2===0)?gGreen:gWhite;
    group.circle(rad*2).center(nucleons[i][0],nucleons[i][1]).fill(col).stroke({color:'#666',width:0.4});
  }
}

function drawNeutron(group,cx,cy,r){
  group.circle(r*2).center(cx,cy).fill(gNeutron).stroke({color:'#888',width:0.6});
}

function drawArrow(group,x1,y1,x2,y2,color,width){
  color=color||'#222';width=width||2.5;
  var dx=x2-x1,dy=y2-y1;
  var len=Math.sqrt(dx*dx+dy*dy);
  var ux=dx/len,uy=dy/len;
  var headLen=12,headW=6;
  group.line(x1,y1,x2-ux*headLen,y2-uy*headLen).stroke({color:color,width:width});
  var hx=x2,hy=y2;
  var bx=x2-ux*headLen,by=y2-uy*headLen;
  var px=-uy*headW,py=ux*headW;
  group.polygon([[hx,hy],[bx+px,by+py],[bx-px,by-py]]).fill(color);
}

function drawStarburst(group,cx,cy,outerR,innerR,points,color){
  var pts=[];
  for(var i=0;i<points*2;i++){
    var angle=(Math.PI*2*i)/(points*2)-Math.PI/2;
    var r=(i%2===0)?outerR:innerR;
    pts.push([cx+Math.cos(angle)*r,cy+Math.sin(angle)*r]);
  }
  group.polygon(pts).fill(color).stroke({color:'#c8a020',width:1.5});
}

// ===== STAGE GROUPS (always visible, dimmed via opacity) =====
var stageNeutron=draw.group();   // incoming neutron + arrow + flash + U-235
var stageU236=draw.group();      // arrow + U-236
var stageProducts=draw.group();  // diverging arrows + Kr + Ba + energy + neutrons

// --- Stage 1: Neutron + U-235 ---
drawNeutron(stageNeutron,50,260,14);
stageNeutron.text('1').attr({'font-size':14,x:36,y:282,'font-weight':'bold'});
stageNeutron.text('0').attr({'font-size':14,x:36,y:296,'font-weight':'bold'});
stageNeutron.text('n').attr({'font-size':16,x:48,y:296,'font-style':'italic','font-weight':'bold'});
drawArrow(stageNeutron,75,260,155,260);
// Impact flash
for(var i=0;i<7;i++){
  var angle=Math.PI*0.25+i*Math.PI*0.22;
  var fx=160+Math.cos(angle)*22;
  var fy=260+Math.sin(angle)*22;
  stageNeutron.line(160,260,fx,fy).stroke({color:'#bbb',width:1.8});
}
// U-235 cluster
drawCluster(stageNeutron,260,260,85,85,50,42,false);
stageNeutron.text('235').attr({'font-size':18,x:238,y:360,'font-weight':'bold'});
stageNeutron.text('92').attr({'font-size':18,x:238,y:378,'font-weight':'bold'});
stageNeutron.text('U').attr({'font-size':22,x:262,y:378,'font-style':'italic','font-weight':'bold'});

// --- Stage 2: U-236 ---
drawArrow(stageU236,360,260,440,260);
// Red instability outline (dumbbell)
var outlinePts=[];
for(var i=0;i<=80;i++){
  var t=i/80;
  var angle=t*Math.PI*2;
  var rx=68,ry=115;
  var x=530+Math.cos(angle)*rx;
  var y=260+Math.sin(angle)*ry;
  var normY=Math.sin(angle);
  var pinch=1-0.32*Math.exp(-normY*normY*6);
  x=530+(x-530)*pinch;
  outlinePts.push([x,y]);
}
stageU236.polygon(outlinePts).fill('none').stroke({color:'#c0392b',width:3});
drawCluster(stageU236,530,260,62,108,52,77,true);
stageU236.text('236').attr({'font-size':18,x:508,y:392,'font-weight':'bold'});
stageU236.text('92').attr({'font-size':18,x:508,y:410,'font-weight':'bold'});
stageU236.text('U').attr({'font-size':22,x:532,y:410,'font-style':'italic','font-weight':'bold'});
stageU236.text('Unstable nucleus').attr({'font-size':15,x:470,y:432,'font-weight':'bold'});

// --- Stage 3: Products ---
drawArrow(stageProducts,600,195,670,130);
drawArrow(stageProducts,600,325,670,390);
// Kr-92
var krGroup=stageProducts.group();
drawCluster(krGroup,740,120,55,55,30,123,false);
krGroup.text('92').attr({'font-size':16,x:800,y:108,'font-weight':'bold'});
krGroup.text('36').attr({'font-size':16,x:800,y:124,'font-weight':'bold'});
krGroup.text('Kr').attr({'font-size':20,x:820,y:124,'font-style':'italic','font-weight':'bold'});
// Ba-141
var baGroup=stageProducts.group();
drawCluster(baGroup,740,400,60,60,36,256,false);
baGroup.text('141').attr({'font-size':16,x:806,y:388,'font-weight':'bold'});
baGroup.text('56').attr({'font-size':16,x:806,y:404,'font-weight':'bold'});
baGroup.text('Ba').attr({'font-size':20,x:828,y:404,'font-style':'italic','font-weight':'bold'});
// Energy starburst
var energyGroup=stageProducts.group();
drawStarburst(energyGroup,740,260,55,24,12,'#f0c840');
energyGroup.text('Energy').attr({'font-size':16,x:710,y:266,'font-weight':'bold',fill:'#333'});
// Three ejected neutrons
drawArrow(stageProducts,810,190,870,175);
drawArrow(stageProducts,810,260,870,260);
drawArrow(stageProducts,810,330,870,345);
drawNeutron(stageProducts,890,170,11);
drawNeutron(stageProducts,890,260,11);
drawNeutron(stageProducts,890,350,11);
stageProducts.text('3').attr({'font-size':18,x:915,y:255,'font-weight':'bold'});
stageProducts.text('1').attr({'font-size':13,x:930,y:245,'font-weight':'bold'});
stageProducts.text('0').attr({'font-size':13,x:930,y:258,'font-weight':'bold'});
stageProducts.text('n').attr({'font-size':16,x:942,y:258,'font-style':'italic','font-weight':'bold'});

// Clickable products
krGroup.css('cursor','pointer');
krGroup.on('click',function(){showPopup('Krypton-92','⁹²₃₆Kr is a fission fragment with 36 protons and 56 neutrons. It is a stable end product and does NOT continue the chain reaction.');});
krGroup.on('mousemove',function(e){showTooltip('Kr-92: fission fragment (does not continue chain)',e);});
krGroup.on('mouseleave',hideTooltip);
baGroup.css('cursor','pointer');
baGroup.on('click',function(){showPopup('Barium-141','¹⁴¹₅₆Ba is a fission fragment with 56 protons and 85 neutrons. Like Kr-92, it is a heavy end product that does NOT carry the chain.');});
baGroup.on('mousemove',function(e){showTooltip('Ba-141: fission fragment (does not continue chain)',e);});
baGroup.on('mouseleave',hideTooltip);
energyGroup.css('cursor','pointer');
energyGroup.on('click',function(){showPopup('Energy Release','About 200 MeV is released per fission, mostly as kinetic energy of the fragments. This is ~10 million times more energy per atom than chemical reactions.');});
energyGroup.on('mousemove',function(e){showTooltip('~200 MeV released per fission event',e);});
energyGroup.on('mouseleave',hideTooltip);

// ===== BOTTOM EQUATION =====
var eqGroup=draw.group();
var eqY=530;
eqGroup.text('235').attr({'font-size':16,x:60,y:eqY-14,'font-weight':'bold'});
eqGroup.text('92').attr({'font-size':16,x:60,y:eqY+2,'font-weight':'bold'});
eqGroup.text('U').attr({'font-size':20,x:82,y:eqY+2,'font-style':'italic','font-weight':'bold'});
eqGroup.text('+').attr({'font-size':20,x:108,y:eqY+2});
eqGroup.text('1').attr({'font-size':13,x:128,y:eqY-10,'font-weight':'bold'});
eqGroup.text('0').attr({'font-size':13,x:128,y:eqY+3,'font-weight':'bold'});
eqGroup.text('n').attr({'font-size':17,x:140,y:eqY+3,'font-style':'italic','font-weight':'bold'});
drawArrow(eqGroup,165,eqY,230,eqY,'#222',2.5);
eqGroup.text('236').attr({'font-size':16,x:245,y:eqY-14,'font-weight':'bold'});
eqGroup.text('92').attr({'font-size':16,x:245,y:eqY+2,'font-weight':'bold'});
eqGroup.text('U').attr({'font-size':20,x:268,y:eqY+2,'font-style':'italic','font-weight':'bold'});
drawArrow(eqGroup,295,eqY,360,eqY,'#222',2.5);
eqGroup.text('141').attr({'font-size':16,x:375,y:eqY-14,'font-weight':'bold'});
eqGroup.text('56').attr({'font-size':16,x:375,y:eqY+2,'font-weight':'bold'});
eqGroup.text('Ba').attr({'font-size':20,x:398,y:eqY+2,'font-style':'italic','font-weight':'bold'});
eqGroup.text('+').attr({'font-size':20,x:430,y:eqY+2});
eqGroup.text('92').attr({'font-size':16,x:455,y:eqY-14,'font-weight':'bold'});
eqGroup.text('36').attr({'font-size':16,x:455,y:eqY+2,'font-weight':'bold'});
eqGroup.text('Kr').attr({'font-size':20,x:478,y:eqY+2,'font-style':'italic','font-weight':'bold'});
eqGroup.text('+').attr({'font-size':20,x:510,y:eqY+2});
eqGroup.text('3').attr({'font-size':18,x:535,y:eqY+2,'font-weight':'bold'});
eqGroup.text('1').attr({'font-size':13,x:550,y:eqY-10,'font-weight':'bold'});
eqGroup.text('0').attr({'font-size':13,x:550,y:eqY+3,'font-weight':'bold'});
eqGroup.text('n').attr({'font-size':17,x:562,y:eqY+3,'font-style':'italic','font-weight':'bold'});

// ===== CHAIN REACTION PANEL =====
var chainPanel=draw.group();
chainPanel.line(30,580,1170,580).stroke({color:'#ccc',width:1});
chainPanel.text('Chain Reaction').attr({'font-size':15,x:30,y:600,'font-weight':'bold',fill:'#444'});

var chainTreeGroup=draw.group();

function drawChainTree(gen){
  chainTreeGroup.clear();
  var startY=630;
  var nodeR=8;
  var levelH=50;
  var centerX=600;

  // Gen 0
  var positions=[[centerX,startY]];
  drawNeutron(chainTreeGroup,centerX,startY,nodeR);
  chainTreeGroup.text('Gen 0: 1 fission').attr({'font-size':12,x:centerX+20,y:startY+5,fill:'#555','font-weight':'bold'});

  for(var g=1;g<=gen;g++){
    var prevPositions=positions.slice();
    positions=[];
    var count=Math.pow(3,g);
    var totalWidth=Math.min(1000,count*30);
    var spacing=totalWidth/(count-1||1);
    var startX=centerX-totalWidth/2;
    for(var i=0;i<count;i++){
      var x=startX+i*spacing;
      var y=startY+g*levelH;
      positions.push([x,y]);
      drawNeutron(chainTreeGroup,x,y,nodeR*0.85);
      var parentIdx=Math.floor(i/3);
      if(parentIdx<prevPositions.length){
        chainTreeGroup.line(prevPositions[parentIdx][0],prevPositions[parentIdx][1]+nodeR,x,y-nodeR*0.85).stroke({color:'#999',width:1.2});
      }
    }
    chainTreeGroup.text('Gen '+g+': '+count+' fissions').attr({'font-size':12,x:centerX+totalWidth/2+25,y:startY+g*levelH+5,fill:'#555','font-weight':'bold'});
  }
}
drawChainTree(0);

// ===== HIGHLIGHTING (opacity-based, never hide) =====
var highlightStates=['Full sequence','Neutron absorbed','U-236 deforms','Fission products'];
var currentHighlight=0;

function setHighlight(state){
  var idx=highlightStates.indexOf(state);
  if(idx<0)idx=0;
  currentHighlight=idx;

  var opNeutron=1,opU236=1,opProducts=1;
  if(idx===1){opNeutron=1;opU236=0.3;opProducts=0.3;}
  else if(idx===2){opNeutron=0.3;opU236=1;opProducts=0.3;}
  else if(idx===3){opNeutron=0.3;opU236=0.3;opProducts=1;}

  stageNeutron.attr({opacity:opNeutron});
  stageU236.attr({opacity:opU236});
  stageProducts.attr({opacity:opProducts});

  var btn=document.getElementById('fissionHighlightInput');
  if(btn)btn.textContent='Highlight: '+state;
}

function cycleHighlight(){
  currentHighlight=(currentHighlight+1)%highlightStates.length;
  setHighlight(highlightStates[currentHighlight]);
}

function update_chainGeneration(v){
  drawChainTree(v);
}

// ===== DEMO STEPS =====
var demoSteps=[
  {title:'Complete fission sequence',narration:'The full process is visible: a neutron strikes U-235, forming unstable U-236, which splits into Ba-141 and Kr-92 while ejecting three neutrons and releasing energy. The balanced equation below summarizes the reaction.',state:{fissionHighlight:'Full sequence',chainGeneration:0}},
  {title:'Neutron absorption highlighted',narration:'The highlight focuses on the incoming neutron and the U-235 cluster — absorption is the trigger that starts everything.',state:{fissionHighlight:'Neutron absorbed',chainGeneration:0}},
  {title:'U-236 deformation highlighted',narration:'The highlight moves to the elongated, red-outlined U-236 — this intermediate is too distorted to hold together, and its shape foreshadows the split.',state:{fissionHighlight:'U-236 deforms',chainGeneration:0}},
  {title:'Fission products highlighted',narration:'The highlight moves to Ba-141, Kr-92, the energy starburst, and the three ejected neutrons. Click any product to learn its role.',state:{fissionHighlight:'Fission products',chainGeneration:0}},
  {title:'From one fission to a chain',narration:'In the chain-reaction panel below, drag the generation slider: the three released neutrons each trigger a new fission, then nine, then twenty-seven — the multiplying neutron population is the chain reaction.',state:{fissionHighlight:'Full sequence',chainGeneration:3}}
];
var demoIdx=0;

function applyDemoStep(idx){
  demoIdx=idx;
  var step=demoSteps[idx];
  document.getElementById('demoNarration').textContent=step.narration;
  document.getElementById('stepLabel').textContent=(idx+1)+'/'+demoSteps.length;
  if(step.state.fissionHighlight)setHighlight(step.state.fissionHighlight);
  if(step.state.chainGeneration!==undefined){
    document.getElementById('chainGenerationInput').value=step.state.chainGeneration;
    document.getElementById('chainGenerationVal').value=step.state.chainGeneration;
    drawChainTree(step.state.chainGeneration);
  }
}

window.prevStep=function(){if(demoIdx>0)applyDemoStep(demoIdx-1);};
window.nextStep=function(){if(demoIdx<demoSteps.length-1)applyDemoStep(demoIdx+1);};
window.cycleHighlight=cycleHighlight;
window.update_chainGeneration=update_chainGeneration;

// Initialize: full sequence visible
setHighlight('Full sequence');
applyDemoStep(0);
window.__markRendered();
})();
