    var minDist=Math.min(rx,ry)*0.18;
    for(var i=0;i<nucleons.length;i++){
      var dx=x-nucleons[i][0],dy=y-nucleons[i][1];
      if(dx*dx+dy*dy<minDist*minDist){tooClose=true;break;}
    }
    if(!tooClose)nucleons.push([x,y]);
  }
  nucleons.sort(function(a,b){return a[1]-b[1];});
  var rad=Math.min(rx,ry)/Math.sqrt(count)*2.6;
  for(var i=0;i<nucleons.length;i++){
    var col=(i%2===0)?gGreen:gWhite;
    group.circle(rad*2).center(nucleons[i][0],nucleons[i][1]).fill(col).stroke({color:'#666',width:0.3});
  }
}

function drawNeutron(group,cx,cy,r){
  group.circle(r*2).center(cx,cy).fill(gNeutron).stroke({color:'#888',width:0.6});
}

function drawArrow(group,x1,y1,x2,y2,color,width){
  color=color||'#222';width=width||2.5;
  var dx=x2-x1,dy=y2-y1;
  var len=Math.sqrt(dx*dx+dy*dy);
  var ux=dx/len,uy=dy/len;
  var headLen=12,headW=6;
  group.line(x1,y1,x2-ux*headLen,y2-uy*headLen).stroke({color:color,width:width});
  var hx=x2,hy=y2;
  var bx=x2-ux*headLen,by=y2-uy*headLen;
  var px=-uy*headW,py=ux*headW;
  group.polygon([[hx,hy],[bx+px,by+py],[bx-px,by-py]]).fill(color);
}

function drawStarburst(group,cx,cy,outerR,innerR,points,color){
  var pts=[];
  for(var i=0;i<points*2;i++){
    var angle=(Math.PI*2*i)/(points*2)-Math.PI/2;
    var r=(i%2===0)?outerR:innerR;
    pts.push([cx+Math.cos(angle)*r,cy+Math.sin(angle)*r]);
  }
  group.polygon(pts).fill(color).stroke({color:'#c8a020',width:1.5});
}

