var chainTreeGroup=draw.group();

function drawChainTree(gen){
  chainTreeGroup.clear();
  var startY=630;
  var nodeR=8;
  var levelH=50;
  var centerX=600;

  // Gen 0
  var positions=[[centerX,startY]];
  drawNeutron(chainTreeGroup,centerX,startY,nodeR);
  chainTreeGroup.text('Gen 0: 1 fission').attr({'font-size':12,x:centerX+20,y:startY+5,fill:'#555','font-weight':'bold'});

  for(var g=1;g<=gen;g++){
    var prevPositions=positions.slice();
    positions=[];
    var count=Math.pow(3,g);
    var totalWidth=Math.min(1000,count*30);
    var spacing=totalWidth/(count-1||1);
    var startX=centerX-totalWidth/2;
    for(var i=0;i<count;i++){
      var x=startX+i*spacing;
      var y=startY+g*levelH;
      positions.push([x,y]);
      drawNeutron(chainTreeGroup,x,y,nodeR*0.85);
      var parentIdx=Math.floor(i/3);
      if(parentIdx<prevPositions.length){
        chainTreeGroup.line(prevPositions[parentIdx][0],prevPositions[parentIdx][1]+nodeR,x,y-nodeR*0.85).stroke({color:'#999',width:1.2});
      }
    }
    chainTreeGroup.text('Gen '+g+': '+count+' fissions').attr({'font-size':12,x:centerX+totalWidth/2+25,y:startY+g*levelH+5,fill:'#555','font-weight':'bold'});
  }
}
