var highlightStates=['Full sequence','Neutron absorbed','U-236 deforms','Fission products'];
var currentHighlight=0;

function setHighlight(state){
  var idx=highlightStates.indexOf(state);
  if(idx<0)idx=0;
  currentHighlight=idx;

  var opNeutron=1,opU236=1,opProducts=1;
  if(idx===1){opNeutron=1;opU236=0.3;opProducts=0.3;}
  else if(idx===2){opNeutron=0.3;opU236=1;opProducts=0.3;}
  else if(idx===3){opNeutron=0.3;opU236=0.3;opProducts=1;}

  stageNeutron.attr({opacity:opNeutron});
  stageU236.attr({opacity:opU236});
  stageProducts.attr({opacity:opProducts});

  var btn=document.getElementById('fissionHighlightInput');
  if(btn)btn.textContent='Highlight: '+state;
}

function cycleHighlight(){
  currentHighlight=(currentHighlight+1)%highlightStates.length;
  setHighlight(highlightStates[currentHighlight]);
}

function update_chainGeneration(v){
  drawChainTree(v);
}

